#!/usr/bin/env bash
# Regenerate the demo clip from scratch, headless, on synthetic sample data.
#
# Generic orchestrator: pick a recipe, run the project's setup, bootstrap the
# recipe's toolchain, record, check the result. Do not edit this file per
# project. The files you change for a new piece are demo/recipe, demo/setup.sh
# and whichever of demo/scene.py (Playwright) or demo/demo.tape (VHS) your
# recipe uses.
#
#   ./demo/record.sh                    regenerate demo/out/ with demo/recipe
#   ./demo/record.sh --clean            throw the toolchain away first
#   DEMO_RECIPE=vhs ./demo/record.sh    override the recipe for one run
#
# A recipe is demo/lib/<name>.sh and must define two functions:
#   recipe_bootstrap        fetch whatever it needs, no root, inside the repo
#   recipe_record OUT_DIR   leave a clip in OUT_DIR, optionally set RECIPE_CLIP

set -euo pipefail

DEMO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$DEMO_DIR/.." && pwd)"
TOOLCHAIN_DIR="$DEMO_DIR/.toolchain"
MAX_SECONDS="${MAX_SECONDS:-35}"

# Each recipe gets its own output directory when asked for one, so a repo that
# ships clips from two recipes does not have one wipe the other.
OUT_DIR="${DEMO_OUT_DIR:-$DEMO_DIR/out}"
case "$OUT_DIR" in /*) ;; *) OUT_DIR="$REPO_ROOT/$OUT_DIR" ;; esac

if [ "${1:-}" = "--clean" ]; then
  rm -rf "$TOOLCHAIN_DIR"
fi

RECIPE="${DEMO_RECIPE:-}"
if [ -z "$RECIPE" ] && [ -f "$DEMO_DIR/recipe" ]; then
  # First non-comment, non-blank line.
  RECIPE="$(grep -v '^[[:space:]]*#' "$DEMO_DIR/recipe" | grep -v '^[[:space:]]*$' | head -1 | tr -d '[:space:]')"
fi
RECIPE="${RECIPE:-vhs}"

RECIPE_LIB="$DEMO_DIR/lib/$RECIPE.sh"
if [ ! -f "$RECIPE_LIB" ]; then
  echo "record.sh: no recipe '$RECIPE'. Available:" >&2
  # A recipe is a lib file that defines recipe_record; everything else in lib/
  # is a shared helper. Asking the files what they are beats keeping a list of
  # the ones to skip, which is a list that goes stale the next time lib/ grows.
  for candidate in "$DEMO_DIR"/lib/*.sh; do
    grep -q '^recipe_record()' "$candidate" || continue
    echo "  $(basename "$candidate" .sh)" >&2
  done
  exit 1
fi

export TOOLCHAIN_DIR DEMO_DIR REPO_ROOT
RECIPE_CLIP=""

say() { printf '\033[1m==>\033[0m %s\n' "$*" >&2; }

say "preparing the project"
"$DEMO_DIR/setup.sh"

# shellcheck source=/dev/null
. "$RECIPE_LIB"

for required in recipe_bootstrap recipe_record; do
  if ! declare -F "$required" >/dev/null; then
    echo "record.sh: $RECIPE_LIB does not define $required()" >&2
    exit 1
  fi
done

say "bootstrapping the $RECIPE toolchain"
recipe_bootstrap

say "recording with $RECIPE"
rm -rf "$OUT_DIR"
mkdir -p "$OUT_DIR"
recipe_record "$OUT_DIR"

CLIP="$RECIPE_CLIP"
if [ -z "$CLIP" ]; then
  CLIP="$(find "$OUT_DIR" -maxdepth 1 -type f \( -name '*.gif' -o -name '*.mp4' \) | sort | head -1)"
fi
if [ -z "$CLIP" ] || [ ! -s "$CLIP" ]; then
  echo "record.sh: the $RECIPE recipe produced no clip" >&2
  exit 1
fi

if command -v ffprobe >/dev/null 2>&1; then
  DURATION="$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$CLIP" 2>/dev/null || echo "")"
else
  DURATION=""
fi

for file in "$OUT_DIR"/*; do
  [ -f "$file" ] || continue
  say "wrote ${file#"$REPO_ROOT"/} ($(du -h "$file" | cut -f1))"
done

if [ -n "$DURATION" ] && [ "${DURATION%.*}" -gt "$MAX_SECONDS" ]; then
  echo "record.sh: clip is ${DURATION%.*}s, over the ${MAX_SECONDS}s budget" >&2
  exit 1
fi
say "clip is ${DURATION%.*}s, inside the ${MAX_SECONDS}s budget"
